function specificity(selector) {
  let s = selector;
  const count = (re) => {
    const m = s.match(re) || [];
    s = s.replace(re, " ");
    return m.length;
  };
  const attrs = count(/\[[^\]]*\]/g);
  const pseudoEls = count(/::[\w-]+/g);
  const ids = count(/#[\w-]+/g);
  const classes = count(/\.[\w-]+/g);
  const pseudoClasses = count(/:[\w-]+/g);
  const types = (s.match(/(^|[\s>+~])[a-zA-Z][\w-]*/g) || []).length;
  return [ids, classes + attrs + pseudoClasses, types + pseudoEls];
}

