coding.referenceSolution:
function cascadeWinner(decls) {
  const cmp = (x, y) => {
    if (x.important !== y.important) return x.important ? 1 : -1;
    for (let i = 0; i < 3; i++) if (x.specificity[i] !== y.specificity[i]) return x.specificity[i] - y.specificity[i];
    return x.order - y.order;
  };
  return decls.reduce((best, d) => (cmp(d, best) > 0 ? d : best)).value;
}

