coding.referenceSolution:
function flexWidths(container, items) {
  const free = container - items.reduce((s, i) => s + i.basis, 0);
  const totalGrow = items.reduce((s, i) => s + i.grow, 0);
  return items.map((i) => {
    if (free <= 0 || totalGrow === 0) return i.basis;
    return Math.round((i.basis + (free * i.grow) / totalGrow) * 100) / 100;
  });
}

