coding.referenceSolution:
function fluidClamp(minPx, maxPx, minVw, maxVw) {
  const slope = (maxPx - minPx) / (maxVw - minVw);
  const base = minPx - slope * minVw;
  const r = (n) => Number(n.toFixed(4));
  return `clamp(${r(minPx / 16)}rem, ${r(base / 16)}rem + ${r(slope * 100)}vw, ${r(maxPx / 16)}rem)`;
}

