coding.referenceSolution:
function gridAreas(rows) {
  const out = {};
  rows.forEach((row, r) => {
    row.trim().split(/\s+/).forEach((name, c) => {
      if (name === "." || name === "") return;
      const a = out[name];
      if (!a) out[name] = { rowStart: r + 1, rowEnd: r + 2, colStart: c + 1, colEnd: c + 2 };
      else {
        a.rowStart = Math.min(a.rowStart, r + 1);
        a.rowEnd = Math.max(a.rowEnd, r + 2);
        a.colStart = Math.min(a.colStart, c + 1);
        a.colEnd = Math.max(a.colEnd, c + 2);
      }
    });
  });
  return out;
}

