function mediaMatches(query, width) {
  const m = query.match(/\((min|max)-width:\s*(\d+)px\)/);
  if (!m) return true;
  return m[1] === "min" ? width >= Number(m[2]) : width <= Number(m[2]);
}

coding.referenceSolution:
function mediaMatches(query, width) {
  const re = /\((min|max)-width:\s*(\d+)px\)/g;
  let m;
  while ((m = re.exec(query))) {
    const n = Number(m[2]);
    if (m[1] === "min" && width < n) return false;
    if (m[1] === "max" && width > n) return false;
  }
  return true;
}

