function matchesCompound(selector, el) {
  const tag = selector.match(/^[a-z][\w-]*/i);
  if (tag && tag[0] !== el.tag) return false;
  const cls = selector.match(/\.([\w-]+)/);
  if (cls && !el.classes.includes(cls[1])) return false;
  return true;
}

coding.referenceSolution:
function matchesCompound(selector, el) {
  const tag = selector.match(/^[a-z][\w-]*/i);
  if (tag && tag[0].toLowerCase() !== el.tag.toLowerCase()) return false;
  const id = selector.match(/#([\w-]+)/);
  if (id && id[1] !== el.id) return false;
  for (const m of selector.matchAll(/\.([\w-]+)/g)) if (!el.classes.includes(m[1])) return false;
  for (const m of selector.matchAll(/\[([\w-]+)\]/g)) if (!(m[1] in el.attrs)) return false;
  return true;
}
